solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
void list_push(linked_list *l, int v) {
    node *n = (node *)malloc(sizeof(node));
    n->value = v;
    n->next = l->head;
    l->head = n;
    l->length++;
}
bool list_pop(linked_list *l, int *v) {
    if (!l->head)
        return false;
    node *n = l->head;
    *v = n->value;
    l->head = n->next;
    l->length--;
    free(n);
    return true;
}
linked_list list_reversed(const linked_list *l) {
    linked_list r = {NULL, 0};
    for (node *n = l->head; n; n = n->next)
        list_push(&r, n->value);
    return r;
}
void list_destroy(linked_list *l) {
    int v;
    while (list_pop(l, &v))
        ;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    linked_list l = {NULL, 0};
    int v;
    assert(!list_pop(&l, &v));
    list_push(&l, 1);
    list_push(&l, 2);
    list_push(&l, 3);
    assert(l.length == 3 && l.head->value == 3);
    linked_list r = list_reversed(&l);
    assert(list_pop(&r, &v) && v == 1);
    assert(list_pop(&l, &v) && v == 3);
    list_destroy(&l);
    list_destroy(&r);
    assert(l.length == 0);

    return 0;
}
